<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require dirname(__DIR__,2).'/app/services/AnalyticsService.php';$u=require_auth();$a=(new \App\Services\AnalyticsService())->build(db(),(int)$u['id'],[]);$q=db()->prepare('SELECT t.symbol,COUNT(*) trades,SUM(t.fees) fees FROM trades t WHERE t.user_id=? AND t.status="closed" GROUP BY t.symbol ORDER BY fees DESC');$q->execute([$u['id']]);$assets=$q->fetchAll();$q=db()->prepare('SELECT ts.name,SUM(t.fees) fees,COUNT(t.id) trades FROM trades t LEFT JOIN trading_systems ts ON ts.id=t.trading_system_id WHERE t.user_id=? AND t.status="closed" GROUP BY ts.id,ts.name ORDER BY fees DESC');$q->execute([$u['id']]);$systems=$q->fetchAll();render('fee_report',['title'=>'Fee Report','a'=>$a,'assets'=>$assets,'systems'=>$systems]);
